cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const half* A, const half* B, half* C, int M, int N, int K) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            sum += (float)A[row * K + k] * (float)B[k * N + col];
        }
        C[row * N + col] = __float2half(sum);
    }
}

extern "C" {
    void launch_matmul(const half* A, const half* B, half* C, int M, int N, int K) {
        dim3 blockSize(16, 16);
        dim3 gridSize((N + blockSize.x - 1) / blockSize.x, (M + blockSize.y - 1) / blockSize.y);
        matmul_kernel<<<gridSize, blockSize>>>(A, B, C, M, N, K);
        cudaDeviceSynchronize();
    }
}
"""

# Load the CUDA extension
